def solve(grid):
    import collections

    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # background colour = most frequent
    freq = collections.Counter(cell for row in grid for cell in row)
    bg = freq.most_common(1)[0][0]

    # non‑background colours
    non_bg = set(freq.keys()) - {bg}
    if not non_bg:
        return grid

    # ------------------------------------------------------------
    # secondary colour S : the colour that touches another non‑bg colour
    # (if more than one, pick the one with the smallest total count)
    # ------------------------------------------------------------
    def has_adjacent_different(colour):
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != colour:
                    continue
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        nb = grid[nr][nc]
                        if nb in non_bg and nb != colour:
                            return True
        return False

    candidates = [c for c in non_bg if has_adjacent_different(c)]
    if candidates:
        S = min(candidates, key=lambda x: freq[x])
    else:
        # fallback – pick the least frequent colour
        S = min(non_bg, key=lambda x: freq[x])

    # ------------------------------------------------------------
    # anchor colours = everything else
    # ------------------------------------------------------------
    anchors = non_bg - {S}

    # ------------------------------------------------------------
    # for each anchor colour compute the set of offsets of S
    # relative to a reference anchor cell that touches S
    # ------------------------------------------------------------
    offset_map = {}          # anchor colour -> list of (dr,dc)

    for anc in anchors:
        # find a reference anchor cell that is orthogonal neighbour of S
        ref = None
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != anc:
                    continue
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == S:
                        ref = (r, c)
                        break
                if ref is not None:
                    break
            if ref is not None:
                break
        if ref is None:
            continue            # this anchor never touches S – nothing to replicate

        # compute offsets from this reference to *all* S cells
        ar, ac = ref
        offs = set()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == S:
                    offs.add((r - ar, c - ac))
        offs.discard((0, 0))   # remove the (non‑)offset
        offset_map[anc] = list(offs)

    # ------------------------------------------------------------
    # apply the pattern for every anchor cell
    # ------------------------------------------------------------
    # keep the original grid untouched while testing positions
    orig = [row[:] for row in grid]

    new_positions = set()

    # helper: generate the four possible orientations
    def orientations(offs):
        yield offs                                     # original
        yield [(dr, -dc) for dr, dc in offs]          # horizontal flip
        yield [(-dr, dc) for dr, dc in offs]          # vertical flip
        yield [(-dr, -dc) for dr, dc in offs]         # both flips

    for anc in anchors:
        offs = offset_map.get(anc, [])
        if not offs:
            continue
        for r in range(rows):
            for c in range(cols):
                if orig[r][c] != anc:
                    continue
                # try each orientation until one fits
                for oriented in orientations(offs):
                    targets = []
                    ok = True
                    for dr, dc in oriented:
                        tr, tc = r + dr, c + dc
                        if not (0 <= tr < rows and 0 <= tc < cols):
                            ok = False
                            break
                        val = orig[tr][tc]
                        if val != bg and val != S:
                            ok = False
                            break
                        targets.append((tr, tc))
                    if ok:
                        new_positions.update(targets)
                        break   # orientation found, stop

    # ------------------------------------------------------------
    # write the new S cells back to the grid
    # ------------------------------------------------------------
    for tr, tc in new_positions:
        grid[tr][tc] = S

    return grid

